mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io, *orig_io;
  int oflags;

  orig = mrb_get_args(mrb, "o", &orig);
  if (!mrb_io_p(orig)) {
    mrb_raise(mrb, E_TYPE_ERROR, "IO required");
  }

  io = mrb_io_get_struct(mrb, copy);
  orig_io = mrb_io_get_struct(mrb, orig);

  if (io->io != NULL) {
    mrb_io_close(mrb, copy);
  }

  if (orig_io->io == NULL) {
    mrb_raise(mrb, E_IO_ERROR, "closed io");
  }

  oflags = fcntl(mrb_io_fd(orig), F_GETFL);
  if (oflags < 0) {
    mrb_sys_fail(mrb, "fcntl(F_GETFL)");
  }

  if (dup2(mrb_io_fd(orig), mrb_io_fd(copy)) < 0) {
    mrb_sys_fail(mrb, "dup2");
  }

  if (fcntl(mrb_io_fd(copy), F_SETFL, oflags) < 0) {
    mrb_sys_fail(mrb, "fcntl(F_SETFL)");
  }

  io->mode = orig_io->mode;
  io->path = orig_io->path;
  io->sync = orig_io->sync;
  io->binmode = orig_io->binmode;

  return copy;
}

mrb_value mrb_io_init_copy(mrb_state *mrb, mrb_value copy) {
  mrb_value original;
  mrb_io *io_orig, *io_dup;
  struct RClass *cIO;

  original = mrb_get_args(mrb, "o", &cIO);
  if (mrb_obj_equal(mrb, copy, original)) {
    return copy;
  }

  mrb_data_initialize(mrb, &copy, NULL, NULL);

  io_orig = mrb_io_ptr(mrb, original);
  io_dup = (mrb_io *)mrb_malloc(mrb, sizeof(*io_dup));
  *io_dup = *io_orig;

  if (io_orig->io != NULL) {
    io_dup->io = mrb_io_dup(mrb, io_orig->io);
    if (io_dup->io == NULL) {
      mrb_free(mrb, io_dup);
      mrb_raise(mrb, E_SYSTEM_ENOENT, "Failed to duplicate IO object");
    }
  }

  mrb_data_init(&copy, io_dup, &mrb_io_type);

  return copy;
}

