mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value original;
  mrb_io *io, *orig_io;
  int oflags, new_fd;

  original = mrb_get_arg1(mrb);
  if (!mrb_io_p(original)) {
    mrb_raise(mrb, E_ARGUMENT_ERROR, "original must be an IO object");
  }

  orig_io = mrb_io_ptr(original);
  io = mrb_io_ptr(copy);
  mrb_data_object_free(mrb, copy); /* finalize existing data if any */

  new_fd = dup(mrb->io);
  if (new_fd == -1) {
    mrb_sys_fail(mrb, "dup");
  }

  oflags = fcntl(mrb->io, F_GETFL, 0);
  if (oflags == -1) {
    mrb_sys_fail(mrb, "fcntl");
  }

  if (fcntl(new_fd, F_SETFL, oflags) == -1) {
    mrb_sys_fail(mrb, "fcntl");
  }

  io->fd = new_fd;
  io->readable = orig_io->readable;
  io->writable = orig_io->writable;
  io->sync = orig_io->sync;

  mrb_obj_iv_copy(mrb, copy, original);

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io, *orig_io;
  int oflags;
  int new_fd;
  int readable;
  int writable;

  orig = mrb_get_args(mrb, "o", &copy);
  if (mrb_obj_equal(mrb, copy, orig)) {
    return copy;
  }

  mrb_data_type *td = mrb->io_type;
  mrb_data_check_type(mrb, orig, "IO");

  orig_io = (struct mrb_io *)mrb_get_datatype(mrb, orig, td);
  if (orig_io == NULL) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type (expected IO)");
  }

  mrb_data_init(mrb, copy, NULL, td);
  io = (struct mrb_io *)mrb_get_datatype(mrb, copy, td);
  if (io == NULL) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "IO allocation failed");
  }

  if (orig_io->fd != -1) {
    new_fd = dup(orig_io->fd);
    if (new_fd == -1) {
      mrb_sys_fail(mrb, "dup");
    }
    io->fd = new_fd;
    oflags = fcntl(orig_io->fd, F_GETFL, 0);
    if (oflags == -1) {
      mrb_sys_fail(mrb, "fcntl");
    }
    fcntl(new_fd, F_SETFL, oflags);
  }

  io->path = strdup(orig_io->path);
  if (io->path == NULL) {
    mrb_sys_fail(mrb, "strdup");
  }

  readable = orig_io->readable;
  writable = orig_io->writable;

  if (readable && (new_fd < 0)) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "failed to duplicate readable IO");
  }

  if (writable && (new_fd < 0)) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "failed to duplicate writable IO");
  }

  io->readable = readable;
  io->writable = writable;
  io->sync = orig_io->sync;

  return copy;
}

mrb_value mrb_io_init_copy(mrb_state *mrb, mrb_value copy) {
  mrb_value original;
  struct mrb_io *io, *orig_io;

  original = mrb_get_args(mrb, "o", &copy);
  if (mrb_equal(mrb, copy, original)) return copy;

  Data_Get_Struct(mrb, copy, struct mrb_io, io);
  Data_Get_Struct(mrb, original, struct mrb_io, orig_io);

  if (io->fd >= 0) {
    mrb_io_close(mrb, copy);
  }

  io->fd = dup(orig_io->fd);
  if (io->fd < 0) {
    mrb_sys_fail(mrb, "dup");
  }

  io->mode = orig_io->mode;
  io->path = orig_io->path;
  io->sync = orig_io->sync;
  io->readable = orig_io->readable;
  io->writable = orig_io->writable;

  return copy;
}
